# Docker Compose configuration for mcp-server-db2i
#
# SECURITY NOTE: This file shows two approaches for credentials:
# 1. Environment variables (simpler, less secure) - credentials visible via docker inspect
# 2. Docker secrets (recommended for production) - credentials stored securely
#
# For production deployments, use Docker secrets or external secret management.
# See README.md for detailed security recommendations.

services:
  mcp-server-db2i:
    # Builds the default odbc image. IBM publishes the ODBC driver for amd64
    # only, so the platform is pinned (arm64 hosts run it under emulation).
    # For the JDBC image, use `target: jt400` and remove the platform line.
    build:
      context: .
      # target: jt400
    platform: linux/amd64
    image: mcp-server-db2i:latest
    container_name: mcp-server-db2i
    stdin_open: true
    tty: true
    # Expose HTTP port (only needed when MCP_TRANSPORT=http or both)
    # ports:
    #   - "${MCP_HTTP_PORT:-3000}:${MCP_HTTP_PORT:-3000}"
    environment:
      # Database connection
      - DB2I_HOSTNAME=${DB2I_HOSTNAME}
      - DB2I_SCHEMA=${DB2I_SCHEMA:-}
      # Driver options. The driver itself is set by the image target.
      - DB2I_ODBC_OPTIONS=${DB2I_ODBC_OPTIONS:-}
      - DB2I_JDBC_OPTIONS=${DB2I_JDBC_OPTIONS:-}
      # Option 1: Plain environment variables (from .env file)
      # Less secure - credentials visible via 'docker inspect'
      - DB2I_USERNAME=${DB2I_USERNAME:-}
      - DB2I_PASSWORD=${DB2I_PASSWORD:-}
      # Option 2: File-based secrets (recommended)
      # More secure - credentials read from mounted files
      # Uncomment these and comment out the plain env vars above to use secrets:
      # - DB2I_USERNAME_FILE=/run/secrets/db2i_username
      # - DB2I_PASSWORD_FILE=/run/secrets/db2i_password

      # Transport settings
      # stdio (default) | http | both
      - MCP_TRANSPORT=${MCP_TRANSPORT:-stdio}

      # HTTP transport settings (only used when MCP_TRANSPORT=http or both)
      - MCP_HTTP_PORT=${MCP_HTTP_PORT:-3000}
      # 127.0.0.1 is correct when nothing publishes this port. Use 0.0.0.0 when ports are published or another container connects in.
      - MCP_HTTP_HOST=${MCP_HTTP_HOST:-127.0.0.1}
      # Extra Host names when clients use a public hostname. Loopback is always allowed.
      - MCP_ALLOWED_HOSTS=${MCP_ALLOWED_HOSTS:-}
      # Set to 1 behind one reverse proxy or tunnel, so rate limits see each client's address
      - MCP_TRUST_PROXY=${MCP_TRUST_PROXY:-false}
      # stateless (default). Set stateful only for 2025-era clients that require Mcp-Session-Id.
      - MCP_SESSION_MODE=${MCP_SESSION_MODE:-stateless}
      - MCP_TOKEN_EXPIRY=${MCP_TOKEN_EXPIRY:-3600}
      - MCP_MAX_SESSIONS=${MCP_MAX_SESSIONS:-100}

      # HTTP authentication mode
      # required (default): Full /auth flow with per-user credentials
      # token: Pre-shared static token, uses env DB credentials
      # none: No auth required (trusted networks only)
      - MCP_AUTH_MODE=${MCP_AUTH_MODE:-required}
      - MCP_AUTH_TOKEN=${MCP_AUTH_TOKEN:-}
      # Allow MCP_AUTH_MODE=none on a non-loopback bind (default: false)
      - MCP_ALLOW_UNAUTHENTICATED_HTTP=${MCP_ALLOW_UNAUTHENTICATED_HTTP:-false}
      # Hosts POST /auth may connect to. Empty uses DB2I_HOSTNAME only.
      - MCP_AUTH_ALLOWED_DB_HOSTS=${MCP_AUTH_ALLOWED_DB_HOSTS:-}
      # OAuth for remote clients such as claude.ai (required mode only)
      - MCP_OAUTH_ENABLED=${MCP_OAUTH_ENABLED:-false}
      - MCP_PUBLIC_URL=${MCP_PUBLIC_URL:-}
      - MCP_OAUTH_REDIRECT_URIS=${MCP_OAUTH_REDIRECT_URIS:-}
      - MCP_OAUTH_SECRET=${MCP_OAUTH_SECRET:-}
      - MCP_OAUTH_REFRESH_EXPIRY=${MCP_OAUTH_REFRESH_EXPIRY:-604800}

      # CORS allowed origins (comma-separated, * for all, empty for same-origin only)
      - MCP_CORS_ORIGINS=${MCP_CORS_ORIGINS:-}

      # TLS settings (for HTTPS)
      - MCP_TLS_ENABLED=${MCP_TLS_ENABLED:-false}
      - MCP_TLS_CERT_PATH=${MCP_TLS_CERT_PATH:-}
      - MCP_TLS_KEY_PATH=${MCP_TLS_KEY_PATH:-}

      # Rate limiting
      - RATE_LIMIT_WINDOW_MS=${RATE_LIMIT_WINDOW_MS:-900000}
      - RATE_LIMIT_MAX_REQUESTS=${RATE_LIMIT_MAX_REQUESTS:-100}
      - RATE_LIMIT_ENABLED=${RATE_LIMIT_ENABLED:-true}
      - AUTH_RATE_LIMIT_MAX_ATTEMPTS=${AUTH_RATE_LIMIT_MAX_ATTEMPTS:-5}
      - AUTH_RATE_LIMIT_WINDOW_MS=${AUTH_RATE_LIMIT_WINDOW_MS:-60000}
      - OAUTH_RATE_LIMIT_MAX_REQUESTS=${OAUTH_RATE_LIMIT_MAX_REQUESTS:-120}
      - OAUTH_RATE_LIMIT_WINDOW_MS=${OAUTH_RATE_LIMIT_WINDOW_MS:-60000}

      # Query limits
      - QUERY_DEFAULT_LIMIT=${QUERY_DEFAULT_LIMIT:-1000}
      - QUERY_MAX_LIMIT=${QUERY_MAX_LIMIT:-10000}
      - QUERY_TIMEOUT=${QUERY_TIMEOUT:-}
      - QUERY_ALLOWED_SCHEMAS=${QUERY_ALLOWED_SCHEMAS:-}
      - QUERY_PARSE_CHECK=${QUERY_PARSE_CHECK:-}

      # Tool selection and response format
      - MCP_TOOLS_ENABLED=${MCP_TOOLS_ENABLED:-}
      - MCP_TOOLS_DISABLED=${MCP_TOOLS_DISABLED:-}
      - MCP_CUSTOM_TOOLS=${MCP_CUSTOM_TOOLS:-}
      - MCP_RESPONSE_FORMAT=${MCP_RESPONSE_FORMAT:-json}

      # Logging
      - LOG_LEVEL=${LOG_LEVEL:-info}
    env_file:
      - .env
    # Uncomment to mount files into the container.
    # volumes:
    #   - ./examples/erp-tools:/tools:ro
    #   - ./certs:/certs:ro
    # Uncomment to use Docker secrets (requires secrets section below):
    # secrets:
    #   - db2i_username
    #   - db2i_password

# Docker secrets configuration (for production use)
# Create secret files in ./secrets/ directory or use external secret management
# secrets:
#   db2i_username:
#     file: ./secrets/db2i_username.txt
#   db2i_password:
#     file: ./secrets/db2i_password.txt

